package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorial
 */
public class MathUtils_factorial_TriageGen1Test {

    @Test
    public void testFactorial_ValidInputs() {
        // Testing boundary and valid values within [1, 20]
        // Note: The code throws IllegalArgumentException if n < 1, 
        // implying n=0 is treated as invalid by this specific implementation's logic.
        assertEquals(1L, MathUtils.factorial(1));
        assertEquals(2L, MathUtils.factorial(2));
        assertEquals(6L, MathUtils.factorial(3));
        assertEquals(120L, MathUtils.factorial(5));
        assertEquals(3628800L, MathUtils.factorial(10));
        assertEquals(2432902008176640000L, MathUtils.factorial(20));
    }








}

